function TryOnExperience({ garmentImage, demoOnly }) {
  const [photo, setPhoto] = useState(null)
  const [result, setResult] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  const readAsDataUrl = file => new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(new Error('Şəkli oxumaq mümkün olmadı.'))
    reader.readAsDataURL(file)
  })

  const selectPhoto = async event => {
    const file = event.target.files?.[0]
    if (!file) return
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      setError('JPG, PNG və ya WEBP formatında şəkil seçin.')
      return
    }
    if (file.size > 8 * 1024 * 1024) {
      setError('Şəkil 8 MB-dan kiçik olmalıdır.')
      return
    }
    try {
      const dataUrl = await readAsDataUrl(file)
      setPhoto({ dataUrl, mimeType: file.type })
      setResult('')
      setError('')
    } catch (uploadError) {
      setError(uploadError.message)
    }
  }

  const generateTryOn = async () => {
    if (!photo || busy) return
    setBusy(true)
    setError('')
    try {
      const garmentResponse = await fetch(garmentImage)
      if (!garmentResponse.ok) throw new Error('Məhsul şəklini yükləmək mümkün olmadı.')
      const garmentBlob = await garmentResponse.blob()
      const garmentDataUrl = await readAsDataUrl(new File([garmentBlob], 'garment', { type: garmentBlob.type || 'image/jpeg' }))
      const response = await fetch('/api/try-on', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          personImage: photo.dataUrl.split(',')[1],
          personMimeType: photo.mimeType,
          garmentImage: garmentDataUrl.split(',')[1],
          garmentMimeType: garmentBlob.type || 'image/jpeg',
          garmentDescription: 'red midi dress, long sleeves, square neckline'
        })
      })
      const payload = await response.json()
      if (!response.ok) throw new Error(payload.error || 'Virtual prova alınmadı. Bir az sonra yenidən yoxlayın.')
      setResult(`data:${payload.mimeType};base64,${payload.image}`)
    } catch (requestError) {
      setError(requestError.message || 'Sorğu zamanı xəta baş verdi.')
    } finally {
      setBusy(false)
    }
  }

  if (import.meta.env.PROD) return <div className="tryon-experience tryon-demo-only"><p>{demoOnly}</p></div>

  return <div className="tryon-experience">
    <label className="tryon-upload-label" htmlFor="tryon-customer-photo"><ImagePlus size={17} /><span><b>{photo ? 'Şəkli dəyiş' : 'Öz şəklini əlavə et'}</b><small>JPG, PNG və ya WEBP · maksimum 8 MB</small></span></label>
    <input id="tryon-customer-photo" className="tryon-file-input" type="file" accept="image/jpeg,image/png,image/webp" onChange={selectPhoto} />
    {photo && <div className="tryon-selected-photo"><img src={photo.dataUrl} alt="Virtual prova üçün seçilmiş şəkliniz"/><span>Şəkil seçildi</span></div>}
    <button className="tryon-generate-button" type="button" disabled={!photo || busy} onClick={generateTryOn}>{busy ? <><span className="tryon-spinner"/>AI geyimi dəyişir...</> : <><Sparkles size={15}/>AI ilə üzərimdə gör</>}</button>
    {error && <p className="tryon-error" role="alert">{error}</p>}
    {result && <div className="tryon-result"><div><CheckCircle2 size={15}/>Virtual prova hazırdır</div><img src={result} alt="Sizin şəklinizdə seçilmiş geyimin virtual prova nəticəsi"/><p>Nəticə illüstrativdir. Geyim təbii görünməsi üçün poza və işıqlandırmadan asılı olaraq dəyişə bilər.</p></div>}
    <p className="tryon-privacy"><LockKeyhole size={12}/>Yüklədiyiniz şəkillər virtual prova üçün Hugging Face demo xidmətinə ötürülür; tətbiq serverimizdə saxlanmır.</p>
  </div>
}

function Dashboard() {
  const [period, setPeriod] = useState('30 gün')
  const [active, setActive] = useState(() => new URLSearchParams(window.location.search).get('section') === 'plans' ? 'Plan və tokenlər' : 'İcmal')
  const [dark, setDark] = useState(() => { try { return localStorage.getItem('provaai-theme') === 'dark' } catch { return false } })
  const [query, setQuery] = useState('')
  const [notice, setNotice] = useState(false)
  const [toast, setToast] = useState('')
  const [billing, setBilling] = useState(() => { try { return { plan:'Starter', allowance:50, used:37, bonus:0, fee:'₼49', renews:'1 noyabr 2026', ...JSON.parse(localStorage.getItem('provaai-billing-demo') || '{}') } } catch { return { plan:'Starter', allowance:50, used:37, bonus:0, fee:'₼49', renews:'1 noyabr 2026' } } })
  const isMonth = period === '30 gün'
  useEffect(() => { document.documentElement.lang = 'az'; document.title = 'Mağaza paneli — ProvaAI'; try { localStorage.setItem('provaai-theme', dark ? 'dark' : 'light') } catch {} }, [dark])
  const sessions = [
    ['Aynur Məmmədova', 'Atelier midi dress', 'M', 'Instagram', 'Satın aldı', '14:32'],
    ['Nigar Əliyeva', 'Soft linen blazer', 'S', 'Birbaşa keçid', 'Məhsula baxır', '14:18'],
    ['Leyla Həsənli', 'Atelier midi dress', 'M', 'Instagram', 'Səbətə əlavə etdi', '13:56'],
    ['Aysel Quliyeva', 'Everyday knit top', 'L', 'Axtarış', 'Virtual prova etdi', '13:41'],
    ['Günel Rzayeva', 'Soft linen blazer', 'M', 'Instagram', 'Satın aldı', '13:12'],
  ]
  const products = [['Atelier midi dress', '348 prova', '12,8%', '/images/tryon-after.jpg'], ['Soft linen blazer', '271 prova', '10,4%', '/images/tryon-before.jpg'], ['Everyday knit top', '186 prova', '8,9%', '/images/tryon-after.jpg']]
  const filteredSessions = sessions.filter(row => row.join(' ').toLowerCase().includes(query.toLowerCase()))
  const showToast = (text) => { setToast(text); window.setTimeout(() => setToast(''), 2600) }
  const exportCsv = () => {
    const csv = ['Müştəri,Məhsul,Ölçü,Kanal,Nəticə,Saat', ...sessions.map(row => row.join(','))].join('\n')
    const url = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' }))
    const link = document.createElement('a'); link.href = url; link.download = 'provaai-demo-hesabat.csv'; link.click(); URL.revokeObjectURL(url)
    showToast('Demo hesabatı endirildi')
  }
  const navItems = [['İcmal', LayoutDashboard], ['Virtual provalar', WandSparkles], ['Müştərilər', Users], ['Məhsullar', ShoppingBag], ['Analitika', ChartNoAxesCombined], ['Plan və tokenlər', CreditCard]]
  const pageDescriptions = { 'Virtual provalar': 'Bütün virtual prova sessiyalarına baxın və nəticələri izləyin.', 'Müştərilər': 'Mağazanızla əlaqə quran müştərilərin ümumi görünüşü.', 'Məhsullar': 'Prova aktivliyini və məhsul performansını bir yerdə idarə edin.', 'Analitika': 'Mağazanızın nəticələrini tarix aralığı üzrə təhlil edin.', 'Plan və tokenlər': 'Aylıq foto kreditlərinizi izləyin və mağazanıza uyğun seçim edin.', 'Tənzimləmələr': 'Mağaza inteqrasiyasını və virtual prova görünüşünü sazlayın.' }
  const choosePlan = (plan, allowance, fee) => { const next = { ...billing, plan, allowance, fee }; setBilling(next); try { localStorage.setItem('provaai-billing-demo', JSON.stringify(next)) } catch {}; showToast(`${plan} planı demo görünüşündə seçildi; ödəniş tutulmadı`) }
  const addTokens = (amount) => { const next = { ...billing, bonus: billing.bonus + amount }; setBilling(next); try { localStorage.setItem('provaai-billing-demo', JSON.stringify(next)) } catch {}; showToast(`+${amount} foto krediti demo balansına əlavə olundu`) }
  const tokenBalance = Math.max(0, billing.allowance - billing.used) + billing.bonus
  const tokenLow = tokenBalance <= Math.ceil(billing.allowance * 0.3)
  return <div className={dark ? 'dashboard-shell dashboard-dark' : 'dashboard-shell'}>
    <aside className="dash-sidebar">
      <a className="brand dash-brand" href="/"><span className="brand-mark"><Sparkles size={17} /></span><span>prova<span className="brand-ai">ai</span></span></a>
      <div className="dash-store-label">MAĞAZA PANELİ</div>
      <button className="dash-store-switch" onClick={() => showToast('Demo mağaza seçilib')}><span className="dash-store-avatar">M</span><span><b>Maison Noir</b><small>maisonnoir.az</small></span><ChevronDownIcon size={15} /></button>
      <div className="dash-nav-label">İŞ PANELİ</div>
      <nav className="dash-nav" aria-label="Panel naviqasiyası">{navItems.map(([name, Icon]) => <button key={name} aria-label={name} aria-current={active === name ? 'page' : undefined} className={active === name ? 'dash-nav-active' : ''} onClick={() => { setActive(name); setQuery('') }}><Icon size={17} /><span>{name}</span>{name === 'Virtual provalar' && <i className="dash-nav-count">12</i>}</button>)}</nav>
      <div className="dash-sidebar-spacer" />
      <div className="dash-help-card"><div className="dash-help-icon"><LifeBuoy size={16} /></div><b>Yardım lazımdır?</b><p>Komandamız sizə kömək etməyə hazırdır.</p><button onClick={() => showToast('Dəstək komandası ilə əlaqə demo rejimindədir')}>Dəstəklə əlaqə <ArrowUpRight size={13} /></button></div>
      <button className={'dash-side-link ' + (active === 'Tənzimləmələr' ? 'dash-nav-active' : '')} onClick={() => { setActive('Tənzimləmələr'); setQuery('') }}><Settings2 size={16} /> Tənzimləmələr</button>
      <a className="dash-side-link" href="/"><ArrowLeftIcon /> Sayta qayıt</a>
      <div className="dash-profile"><div className="dash-user-avatar">RM</div><span><b>Ruhin Məmmədov</b><small>Mağaza sahibi</small></span><button aria-label="Profil menyusu" onClick={() => showToast('Profil menyusu demo rejimindədir')}><ChevronDownIcon size={15} /></button></div>
    </aside>
    <main className="dash-main">
      <header className="dash-topbar"><div className="dash-breadcrumb"><span>Maison Noir</span><ChevronRight size={14} /><b>{active}</b></div><div className="dash-top-actions"><span className="dash-demo-pill"><i /> DEMO MƏLUMATLARI</span><button className={'dash-credit-chip '+(tokenLow?'token-low':'')} onClick={()=>{setActive('Plan və tokenlər');setQuery('')}} aria-label={`${tokenBalance} foto krediti qalıb. Plan və tokenlər səhifəsini aç`}><Coins size={15}/><b>{tokenBalance}</b><span>kredit</span>{tokenLow&&<em>Az qalıb</em>}</button><button className="dash-icon-button dash-theme-toggle" aria-label={dark?'İşıqlı rejimə keç':'Qaranlıq rejimə keç'} title={dark?'İşıqlı rejim':'Qaranlıq rejim'} onClick={()=>setDark(!dark)}>{dark?<Sun size={17}/>:<Moon size={17}/>}</button><button className="dash-icon-button" aria-label="Bildirişlər" onClick={() => setNotice(!notice)}><Bell size={17} /><i /></button><button className="dash-icon-button dash-help-top" aria-label="Yardım" onClick={() => showToast('Dəstək komandası ilə əlaqə demo rejimindədir')}><CircleHelp size={17} /></button><div className="dash-top-avatar">RM</div>{notice && <div className="dash-notice-pop"><b>Bildirişlər</b><p>Bu gün 12 yeni virtual prova tamamlanıb.</p><p>Atelier midi dress ən çox sınanan məhsuldur.</p></div>}</div></header>
      <div className="dash-content">
        <div className="dash-heading-row"><div><div className="dash-eyebrow"><span className="eyebrow-dot" /> MAĞAZA ANALİTİKASI</div><h1>{active === 'İcmal' ? <>Salam, Ruhin <Sparkle size={18} /></> : active}</h1><p>{pageDescriptions[active] || 'Mağazanızın virtual prova nəticələrinə ümumi baxış.'}</p></div><div className="dash-heading-actions"><label className="dash-period"><CalendarDays size={15} /><select value={period} onChange={e => setPeriod(e.target.value)} aria-label="Tarix aralığı"><option>7 gün</option><option>30 gün</option></select><ChevronDownIcon size={14} /></label><button className="dash-export" onClick={exportCsv}><Download size={15} /> Hesabatı endir</button></div></div>
        {active === 'İcmal' ? <>
        <div className="dash-kpi-grid">
          <article className="dash-kpi"><div className="dash-kpi-top"><span>Unikal ziyarətçi</span><span className="dash-kpi-icon kpi-violet"><Users size={17} /></span></div><div className="dash-kpi-value">{isMonth ? '2.486' : '684'}<small> nəfər</small></div><div className="dash-kpi-foot"><span className="dash-positive">↗ {isMonth ? '+18,6%' : '+12,4%'}</span><span> əvvəlki dövrlə müqayisədə</span></div><div className="dash-kpi-spark spark-violet"><svg viewBox="0 0 140 38" preserveAspectRatio="none"><path d="M0 31 C17 27 19 17 35 22 S59 28 72 15 S91 25 108 10 S125 14 140 3" /></svg></div></article>
          <article className="dash-kpi"><div className="dash-kpi-top"><span>Virtual prova</span><span className="dash-kpi-icon kpi-coral"><WandSparkles size={17} /></span></div><div className="dash-kpi-value">{isMonth ? '1.842' : '492'}<small> dəfə</small></div><div className="dash-kpi-foot"><span className="dash-positive">↗ {isMonth ? '+24,2%' : '+16,8%'}</span><span> əvvəlki dövrlə müqayisədə</span></div><div className="dash-kpi-spark spark-coral"><svg viewBox="0 0 140 38" preserveAspectRatio="none"><path d="M0 33 C17 31 18 23 34 27 S52 8 70 17 S91 12 105 17 S124 7 140 2" /></svg></div></article>
          <article className="dash-kpi"><div className="dash-kpi-top"><span>Prova → səbət</span><span className="dash-kpi-icon kpi-green"><ChartNoAxesCombined size={17} /></span></div><div className="dash-kpi-value">{isMonth ? '12,4%' : '11,8%'}</div><div className="dash-kpi-foot"><span className="dash-positive">↗ +2,1%</span><span> əvvəlki dövrlə müqayisədə</span></div><div className="dash-kpi-spark spark-green"><svg viewBox="0 0 140 38" preserveAspectRatio="none"><path d="M0 29 C16 28 23 18 38 22 S58 12 72 19 S91 8 108 13 S128 8 140 3" /></svg></div></article>
          <article className="dash-kpi"><div className="dash-kpi-top"><span>Prova sonrası sifariş</span><span className="dash-kpi-icon kpi-blue"><ShoppingBag size={17} /></span></div><div className="dash-kpi-value">{isMonth ? '228' : '63'}<small> sifariş</small></div><div className="dash-kpi-foot"><span className="dash-positive">↗ {isMonth ? '+14,8%' : '+9,2%'}</span><span> əvvəlki dövrlə müqayisədə</span></div><div className="dash-kpi-spark spark-blue"><svg viewBox="0 0 140 38" preserveAspectRatio="none"><path d="M0 35 C18 29 21 30 37 24 S56 28 72 16 S94 19 108 9 S126 13 140 2" /></svg></div></article>
        </div>
        <div className="dash-main-grid">
          <section className="dash-panel dash-chart-panel"><div className="dash-panel-head"><div><h2>İstifadə dinamikası</h2><p>Virtual prova və məhsula baxış sayı</p></div><button className="dash-select-button" onClick={() => showToast('Göstərici: virtual provalar və məhsula baxış')}>Bütün göstəricilər <ChevronDownIcon size={14} /></button></div><div className="dash-chart-legend"><span><i className="legend-violet" />Virtual provalar <b>{isMonth ? '1.842' : '492'}</b></span><span><i className="legend-coral" />Məhsula baxış <b>{isMonth ? '4.210' : '1.136'}</b></span></div><div className="dash-chart"><div className="chart-ylabels"><span>500</span><span>375</span><span>250</span><span>125</span><span>0</span></div><svg viewBox="0 0 700 220" preserveAspectRatio="none" role="img" aria-label="Virtual prova və məhsula baxış üzrə demo qrafik"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#8c6bce" stopOpacity=".17"/><stop offset="100%" stopColor="#8c6bce" stopOpacity="0"/></linearGradient></defs><path className="chart-gridline" d="M0 10H700 M0 60H700 M0 110H700 M0 160H700 M0 210H700"/><path className="chart-area" d={isMonth ? 'M0 176 C36 170 40 157 78 164 S118 139 156 148 S195 111 234 132 S272 119 312 127 S349 91 390 106 S429 85 468 97 S508 56 546 78 S585 64 624 72 S663 32 700 39 V210 H0Z' : 'M0 185 C36 178 40 166 78 171 S118 151 156 158 S195 126 234 143 S272 128 312 137 S349 105 390 117 S429 96 468 109 S508 70 546 88 S585 74 624 83 S663 48 700 52 V210 H0Z'} /><path className="chart-line-violet" d={isMonth ? 'M0 176 C36 170 40 157 78 164 S118 139 156 148 S195 111 234 132 S272 119 312 127 S349 91 390 106 S429 85 468 97 S508 56 546 78 S585 64 624 72 S663 32 700 39' : 'M0 185 C36 178 40 166 78 171 S118 151 156 158 S195 126 234 143 S272 128 312 137 S349 105 390 117 S429 96 468 109 S508 70 546 88 S585 74 624 83 S663 48 700 52'} /><path className="chart-line-coral" d="M0 193 C38 187 44 176 78 180 S118 160 156 169 S195 143 234 155 S272 137 312 146 S351 117 390 130 S428 103 468 120 S508 81 546 101 S585 83 624 93 S665 57 700 65" /></svg><div className="chart-xlabels">{(isMonth ? ['01 Okt','05 Okt','09 Okt','13 Okt','17 Okt','21 Okt','25 Okt'] : ['8 Okt','9 Okt','10 Okt','11 Okt','12 Okt','13 Okt','14 Okt']).map(label => <span key={label}>{label}</span>)}</div></div><div className="dash-chart-note"><Activity size={14} /> Göstəricilər seçilmiş tarix aralığına görə yenilənir <span>· Demo məlumatları</span></div></section>
          <section className="dash-panel dash-conversion-panel"><div className="dash-panel-head"><div><h2>Prova nəticələri</h2><p>Son {period} üzrə dönüşüm</p></div><button className="dash-more" aria-label="Daha çox seçim" onClick={() => showToast('Əlavə analitika demo rejimindədir')}>···</button></div><div className="conversion-ring"><div className="ring-center"><b>{isMonth ? '12,4%' : '11,8%'}</b><span>ümumi dönüşüm</span></div></div><div className="conversion-legend"><div><span><i className="ring-dot ring-one" />Virtual prova etdi</span><b>{isMonth ? '1.842' : '492'}</b></div><div><span><i className="ring-dot ring-two" />Səbətə əlavə etdi</span><b>{isMonth ? '684' : '192'}</b></div><div><span><i className="ring-dot ring-three" />Sifariş tamamladı</span><b>{isMonth ? '228' : '63'}</b></div></div><div className="conversion-foot"><span>Prova edənlərin</span><b>{isMonth ? '12,4%' : '11,8%'} alışa keçib</b></div></section>
        </div>
        <div className="dash-lower-grid">
          <section className="dash-panel dash-products-panel"><div className="dash-panel-head"><div><h2>Ən çox sınanan məhsullar</h2><p>Müştərilərin maraq göstərdiyi məhsullar</p></div><button className="dash-text-button" onClick={() => { setActive('Məhsullar'); showToast('Məhsullar bölməsi demo rejimindədir') }}>Hamısına bax <ArrowRight size={14} /></button></div><div className="dash-products-list">{products.map(([name, count, rate, image], i) => <div className="dash-product-row" key={name}><span className="dash-product-rank">0{i + 1}</span><img src={image} alt=""/><span className="dash-product-name"><b>{name}</b><small>Maison Noir · Geyim</small></span><span className="dash-product-tries"><b>{count}</b><small>virtual prova</small></span><span className="dash-product-rate"><b>{rate}</b><small>səbətə keçid</small></span><ArrowUpRight size={15} /></div>)}</div></section>
          <section className="dash-panel dash-sources-panel"><div className="dash-panel-head"><div><h2>Ziyarət mənbələri</h2><p>Müştərilər haradan gəlir?</p></div><button className="dash-more" aria-label="Daha çox seçim" onClick={() => showToast('Mənbə analitikası demo rejimindədir')}>···</button></div><div className="source-row"><div className="source-label"><span className="source-icon source-instagram">◎</span><span><b>Instagram</b><small>Sosial media</small></span></div><b>62%</b><div className="source-bar"><i style={{width:'62%'}} /></div><span className="source-count">1.542</span></div><div className="source-row"><div className="source-label"><span className="source-icon source-direct"><ExternalLink size={15}/></span><span><b>Birbaşa keçid</b><small>Sayt linki</small></span></div><b>24%</b><div className="source-bar"><i style={{width:'24%'}} /></div><span className="source-count">596</span></div><div className="source-row"><div className="source-label"><span className="source-icon source-search"><Search size={15}/></span><span><b>Axtarış</b><small>Google və digər</small></span></div><b>14%</b><div className="source-bar"><i style={{width:'14%'}} /></div><span className="source-count">348</span></div><div className="source-tip"><Sparkle size={14}/><span><b>Kiçik ipucu</b> Instagram paylaşımlarında məhsul linkini əlavə edin.</span></div></section>
        </div>
        <section className="dash-panel dash-activity-panel"><div className="dash-panel-head"><div><h2>Son fəaliyyət</h2><p>Mağazanızdakı son virtual prova sessiyaları</p></div><label className="dash-search"><Search size={15}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Müştəri və ya məhsul axtar..." aria-label="Fəaliyyətdə axtar"/></label></div><div className="dash-table-wrap"><table className="dash-table"><thead><tr><th>MÜŞTƏRİ</th><th>MƏHSUL</th><th>ÖLÇÜ</th><th>MƏNBƏ</th><th>NƏTİCƏ</th><th>SAAT</th></tr></thead><tbody>{filteredSessions.map((row, i) => <tr key={row[0] + i}><td><span className={'table-avatar table-avatar-' + i}>{row[0].split(' ').map(s => s[0]).join('')}</span>{row[0]}</td><td>{row[1]}</td><td><span className="table-size">{row[2]}</span></td><td><span className="table-source">{row[3] === 'Instagram' ? '◎ ' : ''}{row[3]}</span></td><td><span className={'table-status ' + (row[4] === 'Satın aldı' ? 'status-success' : row[4] === 'Səbətə əlavə etdi' ? 'status-cart' : 'status-view')}>{row[4]}</span></td><td className="table-time">{row[5]}</td></tr>)}</tbody></table>{filteredSessions.length === 0 && <div className="dash-empty">Axtarışa uyğun nəticə tapılmadı.</div>}</div><div className="dash-table-foot"><span>Demo məlumatları · Müştəri adları nümunə üçün yaradılıb</span><button onClick={() => showToast('Bütün fəaliyyətlər demo rejimindədir')}>Bütün fəaliyyətə bax <ArrowRight size={13}/></button></div></section>
        </> : <DashboardSubpage active={active} query={query} setQuery={setQuery} sessions={sessions} products={products} period={period} showToast={showToast} exportCsv={exportCsv} billing={billing} choosePlan={choosePlan} addTokens={addTokens} />}
        <footer className="dash-footer"><span>© 2026 ProvaAI · Mağaza paneli</span><span><i /> Sistem normal işləyir <a href="/">Sayta qayıt <ArrowUpRight size={12}/></a></span></footer>
      </div>
      {toast && <div className="dash-toast"><CheckCircle2 size={17}/>{toast}</div>}
    </main>
  </div>
}

function DashboardSubpage({ active, query, setQuery, sessions, products, period, showToast, exportCsv, billing, choosePlan, addTokens }) {
  const [filter, setFilter] = useState('Hamısı')
  const [enabled, setEnabled] = useState(() => { try { return { widget: true, privacy: true, branding: true, notice: false, ...JSON.parse(localStorage.getItem('provaai-demo-settings') || '{}').enabled } } catch { return { widget: true, privacy: true, branding: true, notice: false } } })
  const virtualRows = [
    ...sessions,
    ['Sevinc İsmayılova', 'Everyday knit top', 'S', 'Instagram', 'Satın aldı', '12:48'],
    ['Fidan Cəfərova', 'Soft linen blazer', 'M', 'Birbaşa keçid', 'Səbətə əlavə etdi', '12:25'],
    ['Ləman Abbasova', 'Atelier midi dress', 'L', 'Instagram', 'Virtual prova etdi', '11:52'],
  ]
  const customerRows = [
    ['Aynur Məmmədova', 'aynur.m@email.az', '8', '3', '₼567', 'Bu gün'],
    ['Nigar Əliyeva', 'n.aliyeva@email.az', '5', '1', '₼189', 'Bu gün'],
    ['Leyla Həsənli', 'leyla.h@email.az', '12', '4', '₼756', 'Bu gün'],
    ['Aysel Quliyeva', 'aysel.q@email.az', '3', '0', '—', 'Dünən'],
    ['Günel Rzayeva', 'gunel.r@email.az', '6', '2', '₼378', 'Dünən'],
  ]
  const productRows = [
    ['Atelier midi dress', 'Don · M,L', '348', '12,8%', 'Aktiv', '/images/tryon-after.jpg'],
    ['Soft linen blazer', 'Pencək · S,M,L', '271', '10,4%', 'Aktiv', '/images/tryon-before.jpg'],
    ['Everyday knit top', 'Üst geyim · S,M,L', '186', '8,9%', 'Aktiv', '/images/tryon-after.jpg'],
    ['Evening satin skirt', 'Ətək · XS,S,M', '142', '7,6%', 'Quraşdırılır', '/images/tryon-after.jpg'],
  ]
  const rows = active === 'Virtual provalar' ? virtualRows.filter(row => (filter === 'Hamısı' || row[4] === filter) && row.join(' ').toLowerCase().includes(query.toLowerCase())) : active === 'Müştərilər' ? customerRows.filter(row => row.join(' ').toLowerCase().includes(query.toLowerCase())) : active === 'Məhsullar' ? productRows.filter(row => row.join(' ').toLowerCase().includes(query.toLowerCase())) : []
  const search = <label className="dash-search"><Search size={15}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Axtar..." aria-label="Siyahıda axtar"/></label>
  const stat = (label, value, Icon, tone) => <article className="dash-kpi"><div className="dash-kpi-top"><span>{label}</span><span className={'dash-kpi-icon ' + tone}><Icon size={17}/></span></div><div className="dash-kpi-value">{value}</div><div className="dash-kpi-foot"><span className="dash-positive">↗ +12,8%</span><span> seçilmiş dövrdə</span></div></article>
  if (active === 'Virtual provalar') return <>
    <div className="dash-substats">{stat('Cəmi sessiya', period === '30 gün' ? '1.842' : '492', WandSparkles, 'kpi-violet')}{stat('Tamamlanan', period === '30 gün' ? '1.706' : '461', CheckCircle2, 'kpi-green')}{stat('Səbətə keçid', period === '30 gün' ? '684' : '192', ShoppingBag, 'kpi-coral')}{stat('Orta müddət', '38 san.', Activity, 'kpi-blue')}</div>
    <section className="dash-panel dash-page-panel"><div className="dash-panel-head"><div><h2>Virtual prova sessiyaları</h2><p>Müştərilərin məhsulları sınadığı son sessiyalar</p></div>{search}</div><div className="dash-filter-row">{['Hamısı','Satın aldı','Səbətə əlavə etdi','Virtual prova etdi','Məhsula baxır'].map(item => <button key={item} className={filter === item ? 'dash-filter-active' : ''} onClick={() => setFilter(item)}>{item}</button>)}</div><div className="dash-table-wrap"><table className="dash-table"><thead><tr><th>MÜŞTƏRİ</th><th>MƏHSUL</th><th>ÖLÇÜ</th><th>MƏNBƏ</th><th>NƏTİCƏ</th><th>SAAT</th></tr></thead><tbody>{rows.map((row,i)=><tr key={row[0]+i}><td><span className={'table-avatar table-avatar-'+(i%5)}>{row[0].split(' ').map(s=>s[0]).join('')}</span>{row[0]}</td><td>{row[1]}</td><td><span className="table-size">{row[2]}</span></td><td>{row[3]}</td><td><span className={'table-status '+(row[4]==='Satın aldı'?'status-success':row[4]==='Səbətə əlavə etdi'?'status-cart':'status-view')}>{row[4]}</span></td><td className="table-time">{row[5]}</td></tr>)}</tbody></table>{!rows.length&&<div className="dash-empty">Axtarışa uyğun sessiya tapılmadı.</div>}</div><div className="dash-table-foot"><span>Göstərilir: {rows.length} demo sessiya</span><button onClick={exportCsv}>CSV hesabatını endir <Download size={13}/></button></div></section>
  </>
  if (active === 'Müştərilər') return <>
    <div className="dash-substats">{stat('Unikal müştəri', '1.624', Users, 'kpi-violet')}{stat('Təkrar ziyarət', '38%', Activity, 'kpi-green')}{stat('Prova edənlər', '1.208', WandSparkles, 'kpi-coral')}{stat('Orta sifariş', '₼247', ShoppingBag, 'kpi-blue')}</div>
    <section className="dash-panel dash-page-panel"><div className="dash-panel-head"><div><h2>Müştəri siyahısı</h2><p>Virtual prova edən ziyarətçilər üzrə nümunə məlumatlar</p></div>{search}</div><div className="dash-table-wrap"><table className="dash-table"><thead><tr><th>MÜŞTƏRİ</th><th>E-POÇT</th><th>PROVA</th><th>SİFARİŞ</th><th>ÜMUMİ XƏRC</th><th>SON AKTİVLİK</th></tr></thead><tbody>{rows.map((row,i)=><tr key={row[0]}><td><span className={'table-avatar table-avatar-'+i}>{row[0].split(' ').map(s=>s[0]).join('')}</span>{row[0]}</td><td>{row[1]}</td><td>{row[2]}</td><td>{row[3]}</td><td>{row[4]}</td><td className="table-time">{row[5]}</td></tr>)}</tbody></table>{!rows.length&&<div className="dash-empty">Axtarışa uyğun müştəri tapılmadı.</div>}</div><div className="dash-table-foot"><span>Məxfilik qeydi: burada yalnız demo profilləri göstərilir.</span><button onClick={()=>showToast('Müştəri siyahısı demo məlumatlarından ibarətdir')}>Müştəri məlumatları <ShieldCheck size={13}/></button></div></section>
  </>
  if (active === 'Məhsullar') return <>
    <div className="dash-substats">{stat('Prova aktiv məhsul', '24', ShoppingBag, 'kpi-violet')}{stat('Cəmi məhsul baxışı', '4.210', Eye, 'kpi-blue')}{stat('Orta səbətə keçid', '10,7%', ChartNoAxesCombined, 'kpi-green')}{stat('Quraşdırma gözləyir', '3', Activity, 'kpi-coral')}</div>
    <section className="dash-panel dash-page-panel"><div className="dash-panel-head"><div><h2>Məhsul kataloqu</h2><p>Virtual prova aktivliyinə görə sıralanıb</p></div>{search}</div><div className="dash-table-wrap"><table className="dash-table dash-product-table"><thead><tr><th>MƏHSUL</th><th>KATEQORİYA / ÖLÇÜ</th><th>PROVA</th><th>SƏBƏTƏ KEÇİD</th><th>STATUS</th><th>ƏMƏLİYYAT</th></tr></thead><tbody>{rows.map((row,i)=><tr key={row[0]}><td><span className="dash-product-table-name"><img src={row[5]} alt=""/><b>{row[0]}</b></span></td><td>{row[1]}</td><td>{row[2]}</td><td className="product-conversion">{row[3]}</td><td><span className={'table-status '+(row[4]==='Aktiv'?'status-success':'status-cart')}>{row[4]}</span></td><td><button className="dash-row-action" onClick={()=>showToast(`${row[0]} üçün məhsul ayarları açıldı`)}>İdarə et <ArrowUpRight size={12}/></button></td></tr>)}</tbody></table></div><div className="dash-table-foot"><span>Son sinxronizasiya: bu gün, 14:30 · Demo</span><button onClick={()=>showToast('Məhsullar kataloqu sinxronlaşdırıldı')}>Yenilə <RotateCcw size={12}/></button></div></section>
  </>
  if (active === 'Analitika') return <>
    <div className="dash-substats">{stat('Məhsul baxışı', period==='30 gün'?'4.210':'1.136', Eye, 'kpi-violet')}{stat('Virtual provalar', period==='30 gün'?'1.842':'492', WandSparkles, 'kpi-coral')}{stat('Səbətə keçid', '12,4%', ChartNoAxesCombined, 'kpi-green')}{stat('Prova sonrası satış', '228', ShoppingBag, 'kpi-blue')}</div>
    <div className="dash-analytics-grid"><section className="dash-panel dash-chart-panel"><div className="dash-panel-head"><div><h2>Konversiya mərhələləri</h2><p>Müştəri yolunun addım-addım görünüşü</p></div><span className="dash-demo-tag">DEMO</span></div><div className="analytics-funnel"><div><span><Eye size={15}/>Məhsula baxış</span><b>4.210</b><i><em style={{width:'100%'}}/></i><small>100% · başlanğıc</small></div><div><span><WandSparkles size={15}/>Virtual prova</span><b>1.842</b><i><em style={{width:'72%'}}/></i><small>43,8% · baxışdan prova</small></div><div><span><ShoppingBag size={15}/>Səbətə əlavə</span><b>684</b><i><em style={{width:'46%'}}/></i><small>37,1% · prova sonrası</small></div><div><span><CheckCircle2 size={15}/>Sifariş tamamlandı</span><b>228</b><i><em style={{width:'28%'}}/></i><small>33,3% · səbətdən sifariş</small></div></div></section><section className="dash-panel analytics-insight"><div className="dash-help-icon"><Sparkle size={16}/></div><div className="dash-eyebrow">PROVA AI · İPUCU</div><h2>İnstagramdan gələn ziyarətçilər daha çox prova edir.</h2><p>Demo məlumatlarına əsasən sosial media ziyarətçilərinin prova başlatma ehtimalı daha yüksəkdir.</p><button onClick={()=>showToast('Analitika tövsiyələri demo rejimindədir')}>Tövsiyələrə bax <ArrowRight size={14}/></button></section></div>
    <section className="dash-panel dash-page-panel"><div className="dash-panel-head"><div><h2>Kanal üzrə performans</h2><p>Ziyarət, prova və sifariş göstəriciləri</p></div><button className="dash-text-button" onClick={exportCsv}>Hesabatı endir <Download size={14}/></button></div><div className="dash-channel-grid"><div><span>Kanal</span><b>Instagram</b><b>Birbaşa keçid</b><b>Axtarış</b></div><div><span>Ziyarət</span><b>1.542</b><b>596</b><b>348</b></div><div><span>Prova</span><b>1.102</b><b>458</b><b>282</b></div><div><span>Sifariş</span><b>142</b><b>54</b><b>32</b></div></div></section>
  </>
  if (active === 'Plan və tokenlər') return <PlanTokensPage billing={billing} choosePlan={choosePlan} addTokens={addTokens} showToast={showToast}/>
  return <SettingsPage enabled={enabled} setEnabled={setEnabled} showToast={showToast}/>
}

function PlanTokensPage({ billing, choosePlan, addTokens, showToast }) {
  const remaining = Math.max(0, billing.allowance - billing.used) + billing.bonus
  const usage = Math.min(100, Math.round(billing.used / billing.allowance * 100))
  const plans = [['Starter','Kiçik mağazalar üçün',50,'₼49'],['Growth','Böyüyən mağazalar üçün',250,'₼149'],['Enterprise','Yüksək həcmli mağazalar üçün',1000,'Fərdi']]
  const packs = [[50,'₼19','Kiçik əlavə'],[150,'₼49','Ən çox seçilən'],[500,'₼129','Yüksək həcm']]
  return <>
    <section className="dash-panel token-balance-panel"><div className="token-balance-copy"><div className="dash-eyebrow"><span className="eyebrow-dot"/>AYLIQ KREDİT BALANSI</div><div className="token-balance-number">{remaining}<small> foto krediti qalıb</small></div><p>Bu ay {billing.used} / {billing.allowance} aylıq kredit istifadə edilib.</p><div className="token-progress"><i style={{width:`${usage}%`}}/></div><div className="token-progress-label"><span>{usage}% istifadə olunub</span><span>Yenilənmə: {billing.renews}</span></div></div><div className="token-balance-side"><span className="token-balance-icon"><Coins size={23}/></span><span className="token-current-label">AKTİV PLAN</span><b>{billing.plan}</b><span>{billing.fee}{billing.fee !== 'Fərdi' && ' / ay'}</span><button onClick={()=>showToast('Plan istifadəsi demo statistikasıdır')}>İstifadə tarixçəsi <ArrowUpRight size={13}/></button></div></section>
    <div className="token-page-heading"><div><h2>Planını dəyiş</h2><p>Hər yeni planın aylıq foto krediti hər hesablaşma dövründə yenilənir.</p></div><span><RotateCcw size={14}/> Aylıq yenilənmə</span></div>
    <div className="billing-plans">{plans.map(([name,desc,limit,fee],i)=><article className={'billing-plan '+(billing.plan===name?'billing-plan-current':'')+(i===1?' billing-plan-highlight':'')} key={name}>{i===1&&<span className="billing-plan-badge">ƏN ÇOX SEÇİLƏN</span>}<span className="billing-plan-caption">{name===billing.plan?'SİZİN PLANINIZ':`0${i+1} / PLAN`}</span><h3>{name}</h3><p>{desc}</p><div className="billing-plan-price">{fee}<small>{fee==='Fərdi'?'':'/ ay'}</small></div><div className="billing-plan-credit"><Coins size={15}/><b>{limit===1000?'1.000+':limit}</b> foto krediti / ay</div><button className={billing.plan===name?'billing-plan-button is-current':'billing-plan-button'} disabled={billing.plan===name} onClick={()=>choosePlan(name,limit,fee)}>{billing.plan===name?'Cari plan':'Plana keç'}{billing.plan!==name&&<ArrowRight size={14}/>}</button></article>)}</div>
    <div className="token-page-heading token-addons-heading"><div><h2>Planı dəyişmədən kredit artır</h2><p>Aylıq paketinizə əlavə olaraq birdəfəlik foto krediti alın.</p></div><span><CreditCard size={14}/> Ödənişsiz demo</span></div>
    <div className="token-addon-grid">{packs.map(([amount,price,tag])=><article className="token-addon-card" key={amount}><span className="token-addon-tag">{tag}</span><div><b>+{amount}</b><span>foto krediti</span></div><strong>{price}</strong><button onClick={()=>addTokens(amount)}>Paketi əlavə et <ArrowRight size={14}/></button></article>)}</div>
    <div className="token-footnote"><ShieldCheck size={15}/><span><b>Şəffaf istifadə:</b> 1 uğurlu virtual prova = 1 foto krediti. Aylıq plan krediti dövrün sonunda yenilənir; əlavə paketlər birdəfəlikdir. Bu ekran demo üçündür, ödəniş həyata keçirilmir.</span></div>
  </>
}

function SettingsPage({ enabled, setEnabled, showToast }) {
  const [form, setForm] = useState(() => { try { return { name: 'Maison Noir', url: 'https://maisonnoir.az', email: 'salam@maisonnoir.az', platform: 'WooCommerce', ...JSON.parse(localStorage.getItem('provaai-demo-settings') || '{}').form } } catch { return { name: 'Maison Noir', url: 'https://maisonnoir.az', email: 'salam@maisonnoir.az', platform: 'WooCommerce' } } })
  const toggle = (key) => setEnabled(current => ({ ...current, [key]: !current[key] }))
  const update = (key, value) => setForm(current => ({ ...current, [key]: value }))
  const save = () => { try { localStorage.setItem('provaai-demo-settings', JSON.stringify({ enabled, form })) } catch {}; showToast('Demo tənzimləmələri bu brauzerdə yadda saxlanıldı') }
  const control = (label, help, key) => <label className="settings-toggle-row"><span><b>{label}</b><small>{help}</small></span><input type="checkbox" checked={enabled[key]} onChange={() => toggle(key)} aria-label={label}/><i /></label>
  return <div className="settings-layout"><div className="settings-tabs"><button className="settings-tab-active"><Settings2 size={15}/> Ümumi</button><button onClick={()=>showToast('İnteqrasiya parametrləri nümayiş rejimindədir')}><Code2 size={15}/> İnteqrasiya</button><button onClick={()=>showToast('Bildiriş seçimləri nümayiş rejimindədir')}><Bell size={15}/> Bildirişlər</button></div><section className="dash-panel settings-panel"><div className="dash-panel-head"><div><h2>Mağaza məlumatları</h2><p>Bu məlumatlar yalnız bu brauzerdə demo məqsədilə saxlanılır.</p></div></div><div className="settings-form-grid"><label>Mağazanın adı<input value={form.name} onChange={e=>update('name',e.target.value)}/></label><label>Saytın ünvanı<input value={form.url} onChange={e=>update('url',e.target.value)}/></label><label>Əlaqə e-poçtu<input value={form.email} onChange={e=>update('email',e.target.value)} type="email"/></label><label>Mağaza platforması<select value={form.platform} onChange={e=>update('platform',e.target.value)}><option>WooCommerce</option><option>Shopify</option><option>Wix</option><option>Digər</option></select></label></div><div className="settings-divider"/><div className="dash-panel-head settings-subhead"><div><h2>Virtual prova görünüşü</h2><p>Müştərilərə göstərilən təcrübənin seçimləri</p></div></div><div className="settings-options">{control('Məhsul səhifəsində aktiv et','Virtual prova düyməsini uyğun məhsullarda göstər.','widget')}{control('Foto məxfiliyini qoru','Müştəri fotoları sessiyadan sonra saxlanılmasın.','privacy')}{control('Brend rənglərinə uyğunlaşdır','Düymə görünüşündə mağazanızın rənglərini istifadə et.','branding')}{control('Yeni prova bildirişləri','Yeni sessiya olduqda paneldə bildiriş göstər.','notice')}</div><div className="settings-actions"><span><ShieldCheck size={14}/> Demo seçimləri serverə göndərilmir.</span><button className="dash-export" onClick={save}><Check size={14}/> Dəyişiklikləri yadda saxla</button></div></section></div>
}

function ArrowLeftIcon() { return <ArrowRight size={16} style={{ transform: 'rotate(180deg)' }} /> }

createRoot(document.getElementById('root')).render(window.location.pathname === '/dashboard' ? <Dashboard /> : <App />)
